  padding: 18px;
  background: #f8fafc;
  overflow: auto;
}

.report-shell {
  min-height: 100%;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  padding: 22px;
  border-radius: 10px;
  background: #101828;
  color: white;
}

.eyebrow {
  color: #5eead4;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.hero h1 {
  margin: 5px 0 4px;
  font-size: 34px;
  line-height: 1;
}

.hero p {
  margin: 0;
  color: #cbd5e1;
  font-size: 13px;
}

.filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.filters select,
.filters input,
.filters button {
  height: 36px;
  border: 0;
  border-radius: 7px;
  padding: 0 10px;
  font-weight: 800;
}

.filters select {
  min-width: 190px;
}

.filters button {
  cursor: pointer;
  background: #14b8a6;
  color: #062923;
}

.filters .print-btn {
  background: white;
  color: #101828;
}

.print-header {
  display: none;
}

.summary {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 14px;
}

.summary-card,
.panel {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

.summary-card {
  padding: 14px;
}

.summary-card span,
.panel-head span {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.summary-card strong {
  display: block;
  margin-top: 7px;
  font-size: 24px;
}

.content-grid {
  display: grid;
  grid-template-columns: 0.95fr 1.25fr;
  gap: 14px;
  margin-top: 14px;
}

.panel {
  padding: 16px;
  min-height: 420px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: 14px;
}

.panel-head h2 {
  margin: 4px 0 0;
  font-size: 18px;
}

.bar-chart {
  display: grid;
  gap: 10px;
}

.bar-row {
  display: grid;
  grid-template-columns: 170px 1fr 90px;
  gap: 10px;
  align-items: center;
}

.bar-label {
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bar-track {
  height: 12px;
  border-radius: 999px;
  background: #e5e7eb;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, #2563eb, #14b8a6);
}

.bar-value {
  text-align: right;
  font-size: 12px;
  font-weight: 900;
}

.table-wrap {
  max-height: 520px;
  overflow: auto;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
