const reportTitles = {
  SALES_SUMMARY: "Sales Summary",
  SALES_BY_HOUR: "Sales by Hour",
  SALES_BY_DAY: "Sales by Day",
  SALES_BY_PRODUCT: "Sales by Product",
  SALES_BY_CUSTOMER: "Sales by Customer",
  SALES_BY_WAREHOUSE: "Sales by Warehouse",
  PAYMENT_MIX: "Payment Mix",
  TAX_SUMMARY: "Tax Summary",
  FISCAL_STATUS: "Fiscalization Status"
};
function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(2);
}
function num(value) {
  return Number(value || 0);
}
function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.innerText = value;
}
function setValue(id, value) {
  const el = document.getElementById(id);
  if (el) el.value = value;
}
function todayIso() {
  return new Date().toISOString().slice(0, 10);
}
function monthStart() {
  const d = new Date();
  d.setDate(1);
  return d.toISOString().slice(0, 10);
}
function applyFilters() {
  appsmith.updateModel({
    reportType: document.getElementById("reportType").value,
    dateFrom: document.getElementById("dateFrom").value,
    dateTo: document.getElementById("dateTo").value
  });
  appsmith.triggerEvent("onReportChange");
}
function renderPrintHeader(model = {}) {
  const h = model.printHeader || {};
  const title = reportTitles[model.reportType] || "Sales Report";
  setText("printCompany", h.companyName || "Company");
  setText("printCompanyMeta", [h.companyAddress, h.companyPostalCode, h.companyCity, h.companyTaxNumber ? "Tax No: " + h.companyTaxNumber : "", h.companyEmail, h.companyPhone].filter(Boolean).join(" | "));
  setText("printReportTitle", title);
  setText("printPeriod", `Period: ${model.dateFrom || ""} - ${model.dateTo || ""}`);
  setText("printMeta", `Printed: ${h.printedAt || model.generatedAt || ""} by ${h.printedBy || ""}`);
  const logo = document.getElementById("companyLogo");
  if (logo && h.companyLogoPath) {
    logo.src = h.companyLogoPath;
    logo.style.display = "block";
  }
}
function renderSummary(rows = []) {
  const totalAmount = rows.reduce((s, r) => s + num(r.amountValue), 0);
  const totalCount = rows.reduce((s, r) => s + num(r.countValue), 0);
  const totalQuantity = rows.reduce((s, r) => s + num(r.quantityValue), 0);
  setText("totalAmount", money(totalAmount));
  setText("totalCount", totalCount);
  setText("totalQuantity", qty(totalQuantity));
  setText("rowCount", rows.length);
}
function renderChart(rows = []) {
  const root = document.getElementById("barChart");
  if (!root) return;
  if (!rows.length) {
    root.innerHTML = `<div class="empty">No report data for selected filters.</div>`;
    return;
  }
  const chartRows = rows.slice(0, 14);
  const max = Math.max(...chartRows.map(r => Math.abs(num(r.amountValue))), 1);
  root.innerHTML = chartRows.map(row => {
    const value = Math.abs(num(row.amountValue));
    const width = Math.max(4, Math.round(value / max * 100));
    return `
      <div class="bar-row">
        <div class="bar-label" title="${esc(row.groupLabel)}">${esc(row.groupLabel)}</div>
        <div class="bar-track">
          <div class="bar-fill" style="width:${width}%"></div>
        </div>
        <div class="bar-value">${money(row.amountValue)}</div>
      </div>
    `;
  }).join("");
}
function renderTable(rows = []) {
  const body = document.getElementById("reportRows");
  if (!body) return;
  if (!rows.length) {
    body.innerHTML = `
      <tr>
        <td colspan="5">
          <div class="empty">No report data for selected filters.</div>
        </td>
      </tr>
    `;
    return;
  }
  body.innerHTML = rows.map(row => `
    <tr>
      <td>${esc(row.groupLabel)}</td>
      <td class="right">${num(row.countValue)}</td>
      <td class="right">${money(row.amountValue)}</td>
      <td class="right">${row.quantityValue === null || row.quantityValue === undefined ? "-" : qty(row.quantityValue)}</td>
      <td class="right">${row.extraValue === null || row.extraValue === undefined ? "-" : money(row.extraValue)}</td>
    </tr>
  `).join("");
}
function wireControls(model = {}) {
  setValue("reportType", model.reportType || "SALES_SUMMARY");
  setValue("dateFrom", model.dateFrom || monthStart());
  setValue("dateTo", model.dateTo || todayIso());
  document.getElementById("applyBtn").onclick = applyFilters;
  document.getElementById("todayBtn").onclick = () => {
    setValue("dateFrom", todayIso());
    setValue("dateTo", todayIso());
    applyFilters();
  };
  document.getElementById("monthBtn").onclick = () => {
    setValue("dateFrom", monthStart());
    setValue("dateTo", todayIso());
    applyFilters();
  };
  document.getElementById("printBtn").onclick = () => window.print();
}
function render(model = {}) {
  const rows = model.rows || [];
  const title = reportTitles[model.reportType] || "Sales Report";
  setText("chartTitle", title);
  setText("generatedAt", "Updated: " + (model.generatedAt || ""));
  wireControls(model);
  renderPrintHeader(model);
  renderSummary(rows);
  renderChart(rows);
  renderTable(rows);
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

